#!/usr/bin/env bash
# 008: project stage must regenerate the APEX controller dist/releases/apex/f<id>/f<id>.xml
# generated by an earlier SQLcl version, not refuse it as "edited".
source "$(dirname "$0")/../../lib/common.sh"

work="$RUN_DIR/008"
mkdir -p "$work"
cleanup() { leave_branch; restore_apex_app "$work"; }
isolate_branch 008
trap cleanup EXIT

# A real application change, exported and committed, for stage to process
remove_page_in_apex "${APEX_SPARE_PAGE:-100}" "$work"
fresh_apex_export "$work/export.log"
keep_only_apex_export
commit_all "Application $APEX_APP_ID without page ${APEX_SPARE_PAGE:-100}" \
  || error "export produced no change to commit"

controller="dist/releases/apex/f$APEX_APP_ID/f$APEX_APP_ID.xml"
log="$work/stage.log"
project_stage "$log" && pass "project stage regenerated $controller"
grep -q 'has been edited' "$log" \
  && fail "project stage refuses the $controller generated earlier: it 'has been edited'"
error "project stage failed: $(first_error "$log")"
